<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { createClass, createCourse, getClasses, getCourses, getTeacherStudents, saveClassMembers } from '@/api/teacher'
import type { Course, TeacherStudent, TeachingClass } from '@/types/teacher'
const courses=ref<Course[]>([]),students=ref<TeacherStudent[]>([]),classes=ref<TeachingClass[]>([]),current=ref(''),loading=ref(false),newCourse=ref({title:'',description:''}),newClass=ref(''),members=ref<Array<string|number>>([]),memberDialog=ref(false),editingClass=ref<TeachingClass>()
async function load(){loading.value=true;try{[courses.value,students.value]=await Promise.all([getCourses(),getTeacherStudents()]);if(!current.value&&courses.value[0])await select(courses.value[0].id)}catch(e){ElMessage.error(e instanceof Error?e.message:'课程数据加载失败')}finally{loading.value=false}}
async function select(id:string){current.value=id;classes.value=await getClasses(id);members.value=[]}
async function addCourse(){if(!newCourse.value.title.trim()){ElMessage.warning('请输入课程名称');return}await createCourse(newCourse.value);newCourse.value={title:'',description:''};await load();ElMessage.success('课程已创建')}
async function addClass(){if(!current.value||!newClass.value.trim()){ElMessage.warning('请选择课程并输入班级名称');return}await createClass({courseId:current.value,name:newClass.value});newClass.value='';classes.value=await getClasses(current.value);ElMessage.success('班级已创建')}
function editMembers(item:TeachingClass){editingClass.value=item;members.value=[...item.memberIds];memberDialog.value=true}
async function persistMembers(){if(!editingClass.value)return;await saveClassMembers(editingClass.value.id,members.value);classes.value=await getClasses(current.value);memberDialog.value=false;ElMessage.success('班级成员已保存')}
onMounted(load)
</script>
<template><main class="page"><div class="head"><div><p>教师 / 教学管理</p><h1>课程与班级</h1></div><el-button type="primary" @click="$router.push('/teacher/tasks')">任务管理</el-button></div><div class="grid"><el-card v-loading="loading"><template #header>新建课程</template><el-input v-model="newCourse.title" placeholder="课程名称"/><el-input v-model="newCourse.description" type="textarea" placeholder="课程说明"/><el-button type="primary" @click="addCourse">创建课程</el-button><el-divider>课程列表</el-divider><el-menu :default-active="current" @select="select"><el-menu-item v-for="course in courses" :key="course.id" :index="course.id">{{course.title}}</el-menu-item></el-menu></el-card><el-card><template #header>班级与学生</template><div class="row"><el-input v-model="newClass" placeholder="班级名称"/><el-button type="primary" @click="addClass">新建班级</el-button></div><el-table :data="classes"><el-table-column prop="name" label="班级"/><el-table-column prop="studentCount" label="学生数" width="100"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="editMembers(row)">设置成员</el-button></template></el-table-column></el-table><el-divider>学生目录</el-divider><el-tag v-for="student in students" :key="student.id" class="tag">{{student.displayName}}（{{student.username}}）</el-tag></el-card></div><el-dialog v-model="memberDialog" title="设置班级成员" width="420px"><el-select v-model="members" multiple filterable placeholder="从学生目录选择学生"><el-option v-for="student in students" :key="student.id" :value="student.id" :label="`${student.displayName}（${student.username}）`"/></el-select><template #footer><el-button @click="memberDialog=false">取消</el-button><el-button type="primary" @click="persistMembers">保存成员</el-button></template></el-dialog></main></template>
<style scoped>.page{max-width:1440px;min-height:100vh;margin:auto;padding:36px 32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.head p{margin:0;color:#64748b;font-size:13px}h1{margin:7px 0;color:#142d4d}.grid{display:grid;grid-template-columns:360px 1fr;gap:20px}.row{display:flex;gap:10px;margin-bottom:14px}.el-input{margin-bottom:10px}.el-select{width:100%}.tag{margin:0 8px 8px 0}@media(max-width:800px){.page{padding:24px 16px}.grid{grid-template-columns:1fr}}</style>
